{
  "headline": "FDA's records trace our supply to plants with VAI and OAI classifications; the closest FDA action before the 2017-10-31 posting was a VAI letter 8 days after posting at Fresenius Kabi, and no action before posting at a registered plant for Hikma or Hospira",
  "headline_cites": ["D11", "D12", "D13", "D19", "D21", "E18", "E32", "E44"],
  "sentences": [
    {
      "text": "FDA first posted the morphine sulfate injection shortage on 2017-10-31 and it remains Current as of 2026-10-21.",
      "cites": ["E44", "D24"]
    },
    {
      "text": "The shortage listing includes Fresenius Kabi USA, LLC (FEI 3001833549), Hikma Pharmaceuticals USA, Inc. (FEI 2220525), Hospira, Inc., Amphastar Pharmaceuticals, Inc., and Piramal Critical Care Inc.",
      "cites": ["E39", "E40", "E41", "E38", "E42"]
    },
    {
      "text": "Fresenius Kabi inspections ended 2016-02-04, 2017-02-01, and 2017-03-30 were classified VAI, with classification letters dated 2016-08-03 (454 days before posting), 2017-05-02 (estimated), and 2017-11-08 (8 days after posting).",
      "cites": ["D11", "D12", "D13", "D20", "D21", "E26", "E27", "E28"]
    },
    {
      "text": "An OAI inspection at Fresenius Kabi ended 2011-07-08 with a classification letter dated 2017-12-28 (58 days after posting).",
      "cites": ["D19", "E21"]
    },
    {
      "text": "Hikma inspections ended 2019-09-10, 2023-11-03, and 2024-06-12 were classified VAI, with letters dated 2020-02-10, 2023-12-07, and 2024-12-16 — all after the 2017-10-31 posting.",
      "cites": ["D15", "D16", "D17", "D18", "E15", "E16", "E17"]
    },
    {
      "text": "Our Corvale East and Corvale General sites hold Hospira-labeled 2 mg/mL cartridges (NDC 00409189001) and Hikma-labeled 1 mg/mL ampules (NDC 00641601910).",
      "cites": ["E1", "E7", "E2", "E8"]
    },
    {
      "text": "The rule-approved transfer moves 51 units of 2 mg/mL 1 mL from Corvale General (16.7 days on hand) to Corvale East (2.7 days on hand), leaving the sender with 14 days and the receiver with 5 days.",
      "cites": ["D1", "D2", "D25"]
    }
  ]
}
